const geoCoordinates: Record<string, [number, number]> = {
  AS: [-170.7, -14.3], CK: [-159.8, -21.2], FJ: [178.1, -17.7], PF: [-149.5, -17.7], GU: [144.8, 13.4], KI: [172.9, 1.9], MH: [171.2, 7.1], FM: [158.2, 6.9], NR: [166.9, -0.5], NC: [165.6, -21.5], NU: [-169.9, -19.1], MP: [145.7, 15.2], PW: [134.6, 7.5], PG: [143.9, -6.3], PN: [-130.1, -25.1], WS: [-172.1, -13.7], SB: [160.2, -9.6], TK: [-171.8, -9.2], TO: [-175.2, -21.2], TV: [179.1, -8.5], VU: [168.3, -16.2], WF: [-176.2, -13.3],
};

const metricInfo: Record<Metric, { en: string; fr: string; unit: string; color: string }> = {
  sst: { en: "Warming water", fr: "Réchauffement de l’eau", unit: "°C", color: "#9ae3dd" },
  sea: { en: "Sea level", fr: "Niveau de la mer", unit: "m", color: "#a7b9ff" },
  stations: { en: "Monitoring record", fr: "Relevé de surveillance", unit: "sites", color: "#f2c46f" },
  ghg: { en: "GHG / person", fr: "GES / personne", unit: "tCO₂e", color: "#a7b9ff" },
};

function value(value: number | null | undefined, digits = 1, language: ExpansionLanguage = "en") {
  if (value === null || value === undefined || Number.isNaN(value)) return "—";
  return new Intl.NumberFormat(language === "fr" ? "fr-FR" : "en-US", { maximumFractionDigits: digits, minimumFractionDigits: 0 }).format(value);
}

function miniPath(series: SignalPoint[]) {
  if (!series.length) return "";
  const values = series.map((point) => point.value);
  const min = Math.min(...values); const max = Math.max(...values); const range = max - min || 1;
  return series.map((point, index) => `${index === 0 ? "M" : "L"}${(6 + index / Math.max(series.length - 1, 1) * 128).toFixed(1)},${(8 + (max - point.value) / range * 45).toFixed(1)}`).join(" ");
}

export function FieldViewToggle({ mode, onChange, language }: { mode: "schematic" | "atlas"; onChange: (mode: "schematic" | "atlas") => void; language: ExpansionLanguage }) {
  const t = labels[language];
  return <div className="field-view-toggle" role="group" aria-label={t.fieldReference}><button className={mode === "schematic" ? "is-active" : ""} onClick={() => onChange("schematic")}><ScanLine size={13} />{t.schematic}</button><button className={mode === "atlas" ? "is-active" : ""} onClick={() => onChange("atlas")}><MapPinned size={13} />{t.atlas}</button></div>;
}

export function PacificReferenceField({ countries, metric, selectedCode, onSelect, language }: { countries: SignalCountry[]; metric: Metric; selectedCode: string; onSelect: (code: string) => void; language: ExpansionLanguage }) {
  const t = labels[language];
  const records = countries.filter((country) => country.summary[metric]);
  const values = records.map((country) => country.summary[metric]?.latest ?? 0);
  const min = Math.min(...values); const max = Math.max(...values, 1); const info = metricInfo[metric];
  return <div className="pacific-atlas"><svg viewBox="0 0 920 480" role="img" aria-label={`${t.fieldReference}: ${info[language]}`}><defs><pattern id="atlasGrid" width="92" height="68" patternUnits="userSpaceOnUse"><path d="M92 0H0V68" fill="none" stroke="rgba(154,227,221,.10)" strokeWidth="1" /></pattern></defs><rect width="920" height="480" fill="url(#atlasGrid)" /><g fill="none" stroke="rgba(154,227,221,.22)" strokeDasharray="4 9"><path d="M0 105C160 74 270 136 430 102s289 8 490-45" /><path d="M0 275c167 29 285-50 468-11s285-5 452 31" /><path d="M0 410c175-42 323 16 474-18s264 27 446-8" /></g><text x="22" y="34" fill="rgba(235,250,247,.55)" fontSize="11" letterSpacing="2">{t.fieldReference.toUpperCase()} · EQUIRECTANGULAR</text><text x="22" y="456" fill="rgba(235,250,247,.45)" fontSize="10" letterSpacing="1.2">{t.notMap.toUpperCase()}</text>{records.map((country) => { const [longitude, latitude] = geoCoordinates[country.code] ?? [180, -6]; const pacificLongitude = longitude < 0 ? longitude + 360 : longitude; const x = 32 + (pacificLongitude - 130) / 110 * 850; const y = 42 + (20 - latitude) / 50 * 390; const record = country.summary[metric]!; const r = 7 + (record.latest - min) / Math.max(max - min, .0001) * 17; const chosen = country.code === selectedCode; return <g key={country.code} className="atlas-node" role="button" tabIndex={0} onClick={() => onSelect(country.code)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") onSelect(country.code); }} aria-label={`${country.name}: ${value(record.latest, metric === "ghg" ? 1 : 2, language)} ${info.unit}`}><circle cx={x} cy={y} r={r + 6} fill="none" stroke="#8fd8d4" opacity={chosen ? .95 : .34} /><circle cx={x} cy={y} r={r} fill="#082631" stroke={chosen ? "#fffdf4" : "#8fd8d4"} strokeWidth={chosen ? 2.2 : 1.2} /><circle cx={x} cy={y} r={Math.max(3, r * .35)} fill={chosen ? "#f28a70" : info.color} /><text x={x + r + 6} y={y + 4} fill={chosen ? "#fffdf4" : "rgba(235,250,247,.84)"} fontSize="11" fontWeight={chosen ? 700 : 600}>{country.name}</text></g>; })}</svg></div>;
}

export function SSTWall({ countries, onInspect, language }: { countries: SignalCountry[]; onInspect: (code: string) => void; language: ExpansionLanguage }) {
  const t = labels[language];
  const records = countries.filter((country) => country.summary.sst);
  const [ready, setReady] = useState(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  const [activePoint, setActivePoint] = useState<{ code: string; index: number; pointer?: { x: number; y: number } } | null>(null);
  useEffect(() => { if (ready) return; const timer = window.setTimeout(() => setReady(true), 420); return () => window.clearTimeout(timer); }, [ready]);
  return <section className={`sst-wall field-journal-section ${ready ? "is-ready" : "is-calibrating"}`} aria-labelledby="sst-wall-title" aria-busy={!ready}><div className="sst-wall__intro"><p className="mono-label text-[#137d80]">{t.wallKicker}</p><h2 id="sst-wall-title" className="display-serif mt-3">{t.wallTitle}</h2><p>{t.wallCopy}</p><span>{records.length} {t.wallCoverage}</span></div><div className="sst-wall__loading" role="status" aria-live="polite"><i aria-hidden="true" /><span>{t.wallLoading}</span></div><div className="sst-wall__grid">{records.map((country, index) => { const series = country.series.sst; const record = country.summary.sst!; const active = activePoint?.code === country.code ? series[activePoint.index] : null; const values = series.map((point) => point.value); const maximum = Math.max(...values); const minimum = Math.min(...values); const range = Math.max(maximum - minimum, .0001); const pointer = activePoint?.code === country.code ? activePoint.pointer : undefined; const tooltipStyle = pointer ? { left: `${Math.max(14, Math.min(86, (pointer.x / 140) * 100))}%`, top: pointer.y < 31 ? "76%" : "8%" } : undefined; const setIndex = (nextIndex: number, nextPointer?: { x: number; y: number }) => setActivePoint({ code: country.code, index: Math.max(0, Math.min(series.length - 1, nextIndex)), pointer: nextPointer }); return <article key={country.code} className="sst-cell" style={{ "--wall-index": index } as React.CSSProperties} tabIndex={0} role="button" onClick={() => onInspect(country.code)} onFocus={() => setIndex(series.length - 1)} onBlur={() => setActivePoint((current) => current?.code === country.code ? null : current)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onInspect(country.code); } else if (event.key === "ArrowLeft") { event.preventDefault(); setIndex((activePoint?.code === country.code ? activePoint.index : series.length - 1) - 1); } else if (event.key === "ArrowRight") { event.preventDefault(); setIndex((activePoint?.code === country.code ? activePoint.index : series.length - 1) + 1); } }} aria-label={`${t.selectTrace}: ${country.name}. ${t.wallKeyboard}. ${active ? `${active.year}, ${value(active.value, 2, language)} °C` : `${record.latestYear}, ${value(record.latest, 2, language)} °C`}`}><div><span>{country.name}</span><strong>{value(record.latest, 1, language)}°C</strong></div><svg viewBox="0 0 140 62" onPointerMove={(event) => { const rect = event.currentTarget.getBoundingClientRect(); const localX = ((event.clientX - rect.left) / Math.max(rect.width, 1)) * 140; const localY = ((event.clientY - rect.top) / Math.max(rect.height, 1)) * 62; setIndex(Math.round((localX / 140) * (series.length - 1)), { x: localX, y: localY }); }} onPointerLeave={() => setActivePoint(null)} aria-label={`${country.name} SST annual trace`}><path d={miniPath(series)} fill="none" stroke="#8fd8d4" strokeWidth="2" />{series.map((point, pointIndex) => <circle key={point.year} cx={6 + pointIndex / Math.max(series.length - 1, 1) * 128} cy={8 + (maximum - point.value) / range * 45} r={active?.year === point.year ? 4.5 : 2.3} fill={active?.year === point.year ? "#f28a70" : "#9ae3dd"} />)}</svg>{active && <div className={`sst-cell-tooltip${pointer ? " sst-cell-tooltip--pointer" : ""}`} style={tooltipStyle} role="status"><span>{t.wallExact}</span><strong>{active.year} · {value(active.value, 2, language)}°C</strong><small>Pacific Data Hub · SST_ANOM</small></div>}<small>{series[0]?.year}–{series.at(-1)?.year}</small></article>; })}</div></section>;
}

export function ConsequenceSection({ selectedCode, onSelect, language }: { selectedCode: string; onSelect: (code: string) => void; language: ExpansionLanguage }) {
  const t = labels[language];
  const selected = consequencePlaces.find((place) => place.code === selectedCode) ?? consequencePlaces[0];
  const [registerReady, setRegisterReady] = useState(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  const [shareStatus, setShareStatus] = useState<"idle" | "copied">("idle");
  const [shareOpen, setShareOpen] = useState(false);
  const [chartExporting, setChartExporting] = useState(false);
  const [chartStatus, setChartStatus] = useState<"idle" | "success" | "error">("idle");
  const chartRef = useRef<HTMLDivElement>(null);
  useEffect(() => { if (registerReady) return; const timer = window.setTimeout(() => setRegisterReady(true), 460); return () => window.clearTimeout(timer); }, [registerReady]);
  const text = language === "fr" ? `Pacific Signal Room — ${selected.name} : perte directe officielle moyenne de ${value(selected.meanOfficialLossPctGDP, 2, language)} % du PIB sur les années déclarées, avec une couverture ${consequenceMeta.period}. Données officielles déclarées limitées : pas un classement du Pacifique.` : `Pacific Signal Room — ${selected.name}: mean official direct loss of ${value(selected.meanOfficialLossPctGDP, 2, language)}% of GDP across reported years, within ${consequenceMeta.period} coverage. Official reported data are limited, not a Pacific-wide ranking.`;
  const shareUrl = window.location.href;
  const shareFinding = async () => {
    try { if (navigator.share) await navigator.share({ title: "The Pacific Signal Room", text, url: shareUrl }); } catch { /* Closing a device sheet does not alter the evidence view. */ }
  };
  const copyFinding = async () => {
    try { await navigator.clipboard.writeText(`${text}\n${shareUrl}`); } catch { const field = document.createElement("textarea"); field.value = `${text}\n${shareUrl}`; field.style.cssText = "position:fixed;opacity:0"; document.body.appendChild(field); field.select(); document.execCommand("copy"); field.remove(); }
    setShareStatus("copied"); window.setTimeout(() => setShareStatus("idle"), 2200);
  };
  const exportChart = async () => { if (!chartRef.current) return; setChartExporting(true); setChartStatus("idle"); try { const narrow = window.matchMedia("(max-width: 640px)").matches; const canvas = await html2canvas(chartRef.current, { backgroundColor: "#0b303c", scale: narrow ? 2.5 : 3, width: chartRef.current.scrollWidth, windowWidth: Math.max(chartRef.current.scrollWidth, 420), useCORS: true, logging: false }); const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png", 1)); if (!blob) throw new Error("Chart export returned no data."); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `pacific-signal-room_${selected.code}_official-disaster-record.png`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); setChartStatus("success"); window.setTimeout(() => setChartStatus("idle"), 4200); } catch { setChartStatus("error"); window.setTimeout(() => setChartStatus("idle"), 4200); } finally { setChartExporting(false); } };
  if (!registerReady) return <section className="consequence-section consequence-section--loading" aria-labelledby="consequence-title" aria-busy="true"><div className="consequence-section__intro"><p className="mono-label text-[#f28a70]">{t.consequenceKicker}</p><h2 id="consequence-title" className="display-serif">{t.consequenceTitle}</h2><p>{t.consequenceLoadingNote}</p></div><div className="consequence-loading-card" role="status"><div className="consequence-loading-card__heading"><Waves className="signal-spinner" size={18} /><span>{t.consequenceLoading}</span></div><div className="consequence-loading-card__skeleton"><i /><i /><i /></div><div className="consequence-loading-card__ribbon">{Array.from({ length: 19 }, (_, index) => <i key={index} style={{ "--bar-index": index } as React.CSSProperties} />)}</div></div></section>;
  return <section className="consequence-section" aria-labelledby="consequence-title"><div className="consequence-section__intro"><p className="mono-label text-[#f28a70]">{t.consequenceKicker}</p><h2 id="consequence-title" className="display-serif">{t.consequenceTitle}</h2><p>{t.consequenceCopy}</p><div className="consequence-coverage"><span>{consequenceMeta.comparablePlaces}</span><p>{t.coverage}<small>{consequenceMeta.period} · {t.window}</small></p></div><div className="consequence-share-wrap"><button className="consequence-share" onClick={() => setShareOpen((open) => !open)} aria-expanded={shareOpen}><span>{shareStatus === "copied" ? <Check size={15} /> : <Share2 size={15} />}</span>{shareStatus === "copied" ? t.copiedConsequence : t.shareConsequence}</button>{shareOpen && <div className="consequence-share-menu"><button onClick={shareFinding}><Share2 size={13} />{t.deviceShare}</button><button onClick={copyFinding}>{shareStatus === "copied" ? <Check size={13} /> : <Copy size={13} />}{shareStatus === "copied" ? t.copiedConsequence : t.copyConsequence}</button><a href={`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`} target="_blank" rel="noreferrer">in · {t.shareOnLinkedIn}</a><a href={`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(shareUrl)}`} target="_blank" rel="noreferrer">X · {t.shareOnX}</a></div>}</div><span className="sr-only" aria-live="polite">{shareStatus === "copied" ? t.copiedConsequence : ""}</span></div><div ref={chartRef} className="consequence-panel"><div className="consequence-panel__select"><label htmlFor="consequence-place">{t.selectConsequence}</label><select id="consequence-place" value={selected.code} onChange={(event) => onSelect(event.target.value)}>{consequencePlaces.map((place) => <option key={place.code} value={place.code}>{place.name}</option>)}</select></div><div className="consequence-panel__summary"><div><span>{t.meanLoss}</span><strong>{value(selected.meanOfficialLossPctGDP, 2, language)}<small>% GDP</small></strong><p>{selected.lossYears} {t.years}</p></div><div><span>{t.affected}</span><strong>{value(selected.meanDirectlyAffected, 0, language)}<small>people</small></strong><p>{selected.affectedYears} {t.years}</p></div><div><span>{t.contribution}</span><strong className="consequence-panel__dataflow">SDG 11</strong><p>{consequenceMeta.dataflow}</p></div></div><ReportedLossRibbon place={selected} language={language} /><p className="consequence-panel__caveat"><ShieldAlert size={16} />{t.consequenceCaveat}</p><p className="consequence-panel__source">{consequenceMeta.lossSource} · {consequenceMeta.affectedSource} · {consequenceMeta.sourceAgency} · {consequenceMeta.period}</p></div><div className="consequence-chart-export"><button className="signal-button signal-button--seafoam" onClick={exportChart} disabled={chartExporting}>{chartExporting ? <Waves className="signal-spinner" size={16} /> : chartStatus === "success" ? <Check size={16} /> : <Download size={16} />}{chartExporting ? t.chartPreparing : chartStatus === "success" ? t.chartReady : t.chartDownload}</button><span role="status">{chartStatus === "error" ? t.chartError : ""}</span></div></section>;
}

function ReportedLossRibbon({ place, language }: { place: typeof consequencePlaces[number]; language: ExpansionLanguage }) {
  const annual = place.annual.filter((row) => row.officialLossPctGDP !== null);
  const maximum = Math.max(...annual.map((row) => row.officialLossPctGDP ?? 0), 0.01);
  return <div className="consequence-ribbon"><div className="consequence-ribbon__header"><span>{place.name} · {consequenceMeta.period}</span><small>{language === "fr" ? "Une marque par relevé officiel de perte directe" : "One mark per official direct-loss observation"}</small></div><div className="consequence-ribbon__marks">{place.annual.map((row) => row.officialLossPctGDP === null ? <i key={row.year} className="is-missing" title={`${row.year}: no official direct-loss record`} /> : <i key={row.year} title={`${row.year}: ${value(row.officialLossPctGDP, 2, language)}% GDP`} style={{ height: `${12 + (row.officialLossPctGDP / maximum) * 42}px` }} />)}</div></div>;
}

export function EvidenceCompanions({ language }: { language: ExpansionLanguage }) {
  const t = labels[language];
  const cards = [
    { title: t.noaaTitle, copy: t.noaaCopy, url: "https://coralreefwatch.noaa.gov/product/5km/", icon: Waves },
    { title: t.pcrTitle, copy: t.pcrCopy, url: "https://pacific-data.sprep.org/dataset/pacific-catastrophe-risk-assessment-and-financing-initiative-pcrafi", icon: ShieldAlert },
    { title: t.satelliteTitle, copy: t.satelliteCopy, url: "https://cds.climate.copernicus.eu/datasets/satellite-sea-level-global?tab=overview", icon: ScanLine },
  ];
  return <section className="evidence-companions"><div><p className="mono-label text-[#9ae3dd]">{t.companionsKicker}</p><h2 className="display-serif mt-3">{t.companionsTitle}</h2></div><div className="evidence-companions__grid">{cards.map(({ title, copy, url, icon: Icon }) => <article key={title}><Icon size={18} /><h3>{title}</h3><p>{copy}</p><a href={url} target="_blank" rel="noreferrer">{t.openSource} <ExternalLink size={13} /></a></article>)}</div></section>;
}

export function EvidenceCsvDownload({ countries, language }: { countries: SignalCountry[]; language: ExpansionLanguage }) {
  const t = labels[language];
  const download = () => {
    const rows = ["record_type,source,country_or_territory,code,indicator,year,value,unit,coverage_note"];
    const metricRows: [Metric, string, string, string][] = [["sst", "SST_ANOM", "°C", "Pacific Data Hub DF_CLIMATE_CHANGE"], ["sea", "SEA_LVL", "m", "Pacific Data Hub DF_CLIMATE_CHANGE"], ["stations", "METEO_MONITOR_NET", "sites", "Pacific Data Hub DF_CLIMATE_CHANGE"], ["ghg", "GHG_EMI_CAPITA", "tCO2e per person", "Pacific Data Hub DF_CLIMATE_CHANGE"]];
    countries.forEach((country) => metricRows.forEach(([metric, indicator, unit, source]) => country.series[metric].forEach((point) => rows.push(["official_observation", source, country.name, country.code, indicator, point.year, point.value, unit, "annual reported observation"].map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")))));
    consequencePlaces.forEach((place) => place.annual.forEach((row) => { if (row.officialLossPctGDP !== null) rows.push(["official_reported_impact", consequenceMeta.lossSource, place.name, place.code, consequenceMeta.lossIndicator, row.year, row.officialLossPctGDP, "% GDP", "observed zero retained; blank years excluded"].map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")); if (row.directlyAffected !== null) rows.push(["official_reported_impact", consequenceMeta.affectedSource, place.name, place.code, consequenceMeta.affectedIndicator, row.year, row.directlyAffected, "people", "observed zero retained; blank years excluded"].map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")); }));
    const blob = new Blob([rows.join("\n")], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "pacific-signal-room_evidence-data.csv"; link.click(); URL.revokeObjectURL(url);
  };
  return <div className="evidence-csv"><div><p className="mono-label text-[#f2c46f]">{t.sourceManifest}</p><p>{t.csvCopy}</p></div><button className="signal-button signal-button--seafoam" onClick={download}><Download size={16} />{t.csv}</button></div>;
}

/** Signal Room refinement: exact annual observations drive both the active dot and its portal-level callout. */
export function SSTWallPointAnchored({ countries, onInspect, language }: { countries: SignalCountry[]; onInspect: (code: string) => void; language: ExpansionLanguage }) {
  const t = labels[language];
  const records = countries.filter((country) => country.summary.sst);
  const [ready, setReady] = useState(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  const [active, setActive] = useState<{ code: string; index: number; point?: { x: number; y: number } } | null>(null);
  useEffect(() => { if (ready) return; const timer = window.setTimeout(() => setReady(true), 420); return () => window.clearTimeout(timer); }, [ready]);
  const activeCountry = active ? records.find((country) => country.code === active.code) : undefined;
  const activeRecord = activeCountry && active ? activeCountry.series.sst[active.index] : undefined;
  const callout = active?.point && activeRecord && typeof document !== "undefined" ? createPortal(<div className="sst-cell-tooltip sst-cell-tooltip--pointer" style={{ left: `${Math.min(Math.max(106, active.point.x), window.innerWidth - 106)}px`, top: `${Math.max(100, active.point.y - 14)}px` }} role="status"><span>{t.wallExact}</span><strong>{activeRecord.year} · {value(activeRecord.value, 2, language)}°C</strong><small>Pacific Data Hub · SST_ANOM</small></div>, document.body) : null;
  return <><section className={`sst-wall field-journal-section ${ready ? "is-ready" : "is-calibrating"}`} aria-labelledby="sst-wall-title" aria-busy={!ready}><div className="sst-wall__intro"><p className="mono-label text-[#137d80]">{t.wallKicker}</p><h2 id="sst-wall-title" className="display-serif mt-3">{t.wallTitle}</h2><p>{t.wallCopy}</p><span>{records.length} {t.wallCoverage}</span></div><div className="sst-wall__loading" role="status" aria-live="polite"><i aria-hidden="true" /><span>{t.wallLoading}</span></div><div className="sst-wall__grid">{records.map((country, countryIndex) => { const series = country.series.sst; const latest = country.summary.sst!; const values = series.map((point) => point.value); const maximum = Math.max(...values); const minimum = Math.min(...values); const range = Math.max(maximum - minimum, .0001); const keyboardPoint = active?.code === country.code && !active.point && active ? series[active.index] : null; const chooseIndex = (index: number, point?: { x: number; y: number }) => setActive({ code: country.code, index: Math.max(0, Math.min(series.length - 1, index)), point }); const clear = () => setActive((current) => current?.code === country.code ? null : current); return <article key={country.code} className="sst-cell" style={{ "--wall-index": countryIndex } as React.CSSProperties} tabIndex={0} role="button" onClick={() => onInspect(country.code)} onFocus={() => chooseIndex(series.length - 1)} onBlur={clear} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onInspect(country.code); } else if (event.key === "ArrowLeft") { event.preventDefault(); chooseIndex((active?.code === country.code ? active.index : series.length - 1) - 1); } else if (event.key === "ArrowRight") { event.preventDefault(); chooseIndex((active?.code === country.code ? active.index : series.length - 1) + 1); } }} aria-label={`${t.selectTrace}: ${country.name}. ${t.wallKeyboard}. ${keyboardPoint ? `${keyboardPoint.year}, ${value(keyboardPoint.value, 2, language)} °C` : `${latest.latestYear}, ${value(latest.latest, 2, language)} °C`}`}><div><span>{country.name}</span><strong>{value(latest.latest, 1, language)}°C</strong></div><svg viewBox="0 0 140 62" onPointerMove={(event) => { const bounds = event.currentTarget.getBoundingClientRect(); const xInViewBox = ((event.clientX - bounds.left) / Math.max(bounds.width, 1)) * 140; const selectedIndex = Math.max(0, Math.min(series.length - 1, Math.round(((xInViewBox - 6) / 128) * (series.length - 1)))); const selected = series[selectedIndex]; const dotX = 6 + selectedIndex / Math.max(series.length - 1, 1) * 128; const dotY = 8 + (maximum - selected.value) / range * 45; chooseIndex(selectedIndex, { x: bounds.left + dotX / 140 * bounds.width, y: bounds.top + dotY / 62 * bounds.height }); }} onPointerLeave={clear} aria-label={`${country.name} SST annual trace`}><path d={miniPath(series)} fill="none" stroke="#8fd8d4" strokeWidth="2" />{series.map((point, pointIndex) => <circle key={`${point.year}-${pointIndex}`} cx={6 + pointIndex / Math.max(series.length - 1, 1) * 128} cy={8 + (maximum - point.value) / range * 45} r={active?.code === country.code && active.index === pointIndex ? 4.5 : 2.3} fill={active?.code === country.code && active.index === pointIndex ? "#f28a70" : "#9ae3dd"} />)}</svg>{keyboardPoint && <div className="sst-cell-tooltip" role="status"><span>{t.wallExact}</span><strong>{keyboardPoint.year} · {value(keyboardPoint.value, 2, language)}°C</strong><small>Pacific Data Hub · SST_ANOM</small></div>}<small>{series[0]?.year}–{series.at(-1)?.year}</small></article>; })}</div></section>{callout}</>;
}

